+// RF-002: la tasa se configura con TASA_IVA (número entre 0 y 1). Sin variable, 13 %. Un valor inválido es un error.
+export function tasaIva(env = process.env) {
+  const valor = env.TASA_IVA;
+  if (valor === undefined) return TASA_IVA_POR_DEFECTO;
